// Send queued review-gating requests that are due and within business hours; send up to 1 reminder.
const now = $now;
const openH = Number($env.BUSINESS_HOURS_START || 9);
const closeH = Number($env.BUSINESS_HOURS_END || 19);
const hour = now.hour;
const inHours = hour >= openH && hour < closeH;
const biz = $env.BUSINESS_NAME || 'us';
const reminderGap = Number($env.REVIEW_REMINDER_MIN || 1440);
const out = [];
if (!inHours) return out;
for (const item of $input.all()) {
  const r = item.json;
  const status = (r.Status || '').toLowerCase();
  const replied = !!r.Last_Inbound_At;
  if (replied) continue;
  // First ask: Queued and Send_At is due
  if (status.includes('queued')) {
    const due = r.Send_At ? now.toMillis() >= new Date(r.Send_At).getTime() : true;
    if (!due) continue;
    const name = r.Customer_Name ? (' ' + String(r.Customer_Name).split(' ')[0]) : '';
    out.push({ json: { ...r, _msg: `Hi${name}, thanks for choosing ${biz}! How was your experience? Reply with a number 1-5 (5 = great). Your feedback means a lot.`, _new_status: 'Asked - Awaiting Rating', _is_reminder: false } });
    continue;
  }
  // One reminder: Asked but no reply after reminderGap, and not yet reminded
  if (status.includes('awaiting rating') && (r.Reminder_Sent || 'No') !== 'Yes') {
    const askedDue = r.Asked_At ? now.toMillis() >= (new Date(r.Asked_At).getTime() + reminderGap * 60000) : false;
    if (!askedDue) continue;
    out.push({ json: { ...r, _msg: `Just a quick follow-up from ${biz} — we'd love your feedback! Reply 1-5 whenever you have a sec. Thank you!`, _new_status: 'Asked - Awaiting Rating', _is_reminder: true } });
  }
}
return out;
